render:
const { root, params, progress, time, width, height } = ctx;
const canvas = root.querySelector('#ds-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

// 1. OBTENCIÓN Y VALIDACIÓN DE PARÁMETROS
const text = (params.text_content !== undefined && params.text_content !== '') ? params.text_content : "DARK SOULS ES UN VIDEOJUEGO";
const textAlign = params.text_align || "center";
const mainColor = params.text_color || "#B366FF";
const glowColor = params.glow_color || "#8A2BE2";
const bgColor = params.bg_color || "#08030C";
const fontFamily = params.font_family || "Georgia";
const fontWeight = params.font_weight || "bold";
const fontSizeMult = params.font_size_mult !== undefined ? params.font_size_mult : 1.0;
const glowIntensity = params.glow_intensity !== undefined ? params.glow_intensity : 20;
const zoomIntensity = params.zoom_intensity !== undefined ? params.zoom_intensity : 0.45;
const revealStagger = params.reveal_stagger !== undefined ? params.reveal_stagger : 0.6;
const numParticles = params.particle_density !== undefined ? params.particle_density : 80;
const particleColor2 = params.particle_color_2 || "#FF4500";
const particleSpeed = params.particle_speed !== undefined ? params.particle_speed : 1.0;

// Limpiar fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

// 2. CÁLCULO DE OPACIDAD GLOBAL (Fade In / Fade Out)
let globalAlpha = 1;
if (progress < 0.15) {
  globalAlpha = progress / 0.15;
} else if (progress > 0.85) {
  globalAlpha = (1 - progress) / 0.15;
}
globalAlpha = Math.max(0, Math.min(1, globalAlpha));

if (globalAlpha <= 0) return;

// 3. RENDERIZADO DE PARTÍCULAS DE CENIZA / MAGIA
if (numParticles > 0) {
  c.save();
  for (let i = 0; i < numParticles; i++) {
    const seed = i * 137.3;
    const speedY = (30 + (seed % 40)) * particleSpeed;
    const driftX = Math.sin(time * 0.8 + seed) * 25;

    let py = (height + 50 - ((time * speedY + seed * 10) % (height + 100)));
    let px = ((seed * 19.3 + driftX) % width);
    if (px < 0) px += width;

    const size = 1.2 + (seed % 3.0);
    const alpha = (0.3 + Math.sin(time * 2 + seed) * 0.3) * globalAlpha;
    const color = (i % 3 === 0) ? particleColor2 : glowColor;

    c.fillStyle = color;
    c.shadowColor = mainColor;
    c.shadowBlur = glowIntensity > 0 ? 8 : 0;
    c.globalAlpha = Math.max(0, Math.min(1, alpha));

    c.beginPath();
    // Cenizas ligeramente ovaladas o asimétricas
    const rx = size;
    const ry = size * (0.8 + (seed % 0.6));
    c.ellipse(px, py, rx, ry, seed, 0, Math.PI * 2);
    c.fill();
  }
  c.restore();
}

// 4. CONFIGURACIÓN DEL TEXTO Y MÉT TRICAS
const baseFontSize = Math.min(width * 0.055, 65) * fontSizeMult;
c.font = `${fontWeight} ${baseFontSize}px "${fontFamily}", serif`;
c.textBaseline = "middle";

const chars = text.split("");
let unscaledTotalWidth = 0;
const charWidths = chars.map(char => {
  const w = c.measureText(char).width;
  unscaledTotalWidth += w;
  return w;
});

// Determinación del origen según la alineación elegida
let cx = width / 2;
if (textAlign === "left") {
  cx = width * 0.1 + (unscaledTotalWidth / 2);
} else if (textAlign === "right") {
  cx = width * 0.9 - (unscaledTotalWidth / 2);
}
const cy = height / 2;

// Escalado progresivo de zoom
const growthScale = (1 - (zoomIntensity * 0.5)) + (progress * zoomIntensity);
const revealDuration = 0.5;

// 5. DIBUJO DE CARACTERES CINETICOS
c.save();
c.translate(cx, cy);
c.scale(growthScale, growthScale);

let startX = -unscaledTotalWidth / 2;

chars.forEach((char, i) => {
  const charW = charWidths[i];
  const charCX = startX + charW / 2;

  const charDelay = (i / Math.max(1, chars.length)) * (revealDuration * revealStagger);
  const charProgress = Math.max(0, Math.min(1, (progress - charDelay) / 0.2));

  if (charProgress > 0) {
    c.save();

    const charScale = 0.6 + charProgress * 0.4;
    const alpha = charProgress * globalAlpha;

    c.translate(charCX, 0);
    c.scale(charScale, charScale);

    if (glowIntensity > 0) {
      c.shadowColor = glowColor;
      c.shadowBlur = glowIntensity + Math.sin(time * 3 + i) * (glowIntensity * 0.3);
    }
    c.globalAlpha = Math.max(0, Math.min(1, alpha));

    c.fillStyle = mainColor;
    c.textAlign = "center";
    c.fillText(char, 0, 0);

    // Destello de aparición en blanco
    if (charProgress > 0.1 && charProgress < 0.4) {
      c.fillStyle = "#FFFFFF";
      c.globalAlpha = Math.max(0, Math.min(1, ((0.4 - charProgress) / 0.3) * globalAlpha));
      c.fillText(char, 0, 0);
    }

    c.restore();
  }

  startX += charW;
});

c.restore();
